/* مقارنة الفئات */
function famOf(c){var m=modelOf(c);var o=[];cars.forEach(function(x,i){if(x.b===c.b&&x.status!=="hidden"&&modelOf(x)===m)o.push(i)});return o}
var cmpFam=[],cmpSel=[];
function cmpData(idx){
  var secs=[],smap={};
  idx.forEach(function(i){
    var cs=cars[i],sec="مواصفات";
    (cs.specs||[]).forEach(function(r){
      var key,val;
      if(typeof r==="string"){key="f|"+r;val=true}
      else if(r.h){sec=r.h;return}
      else{key="k|"+r[0];val=r[1]}
      var S=smap[sec];if(!S){S=smap[sec]={h:sec,keys:[],rows:{}};secs.push(S)}
      var R=S.rows[key];if(!R){R=S.rows[key]={label:key.slice(2),feat:key.charAt(0)==="f",v:{}};S.keys.push(key)}
      R.v[i]=val;
    });
  });
  return secs;
}
function hasDiff(idx){var r=false;cmpData(idx).forEach(function(S){S.keys.forEach(function(k){var R=S.rows[k],v=idx.map(function(i){return R.v[i]});if(!v.every(function(x){return String(x)===String(v[0])}))r=true})});return r}
function drawCmp(){
  var wrap=$("cmpTbl");wrap.innerHTML="";
  var idx=cmpSel,diff=$("cmpDiff").checked;
  var tb=document.createElement("table"),th=document.createElement("thead"),hr=document.createElement("tr");
  function cell(tag,tx,cl){var e=document.createElement(tag);if(tx!=null)e.textContent=tx;if(cl)e.className=cl;return e}
  hr.appendChild(cell("th",""));
  idx.forEach(function(i){var c=cars[i],h=cell("th");if(c.imgs&&c.imgs.length){var im=document.createElement("img");im.alt=c.b+" "+c.n;thumbImg(im,c.imgs[0]);h.appendChild(im)}h.appendChild(cell("div",c.n,"cn"));h.appendChild(cell("div",priceText(c),"price"));hr.appendChild(h)});
  th.appendChild(hr);tb.appendChild(th);
  var body=document.createElement("tbody");
  function row(label,vals,cl){var tr=document.createElement("tr");if(cl)tr.className=cl;tr.appendChild(cell("td",label));vals.forEach(function(v){tr.appendChild(v)});body.appendChild(tr)}
  var colsV=idx.map(function(i){var c=cars[i];var n=(c.colors&&c.colors.length)?c.colors.length:0;return cell("td",n?n+" ألوان":"—",n?"":"no")});
  var same=true;colsV.forEach(function(v){if(v.textContent!==colsV[0].textContent)same=false});
  if(!(diff&&same))row("الألوان المتوفرة",colsV,same?"":"df");
  var any=false;
  cmpData(idx).forEach(function(S){
    var rows=[];
    S.keys.forEach(function(k){
      var R=S.rows[k],vals=idx.map(function(i){return R.v[i]}),eq=vals.every(function(v){return String(v)===String(vals[0])});
      if(diff&&eq)return;
      var tds=vals.map(function(v){if(v===undefined)return cell("td","—","no");if(v===true)return cell("td","✓","yes");return cell("td",String(v))});
      rows.push([R.label,tds,eq?"":"df"]);
    });
    if(!rows.length)return;
    any=true;
    var sr=document.createElement("tr");sr.className="sec";var sc=cell("td",S.h);sc.colSpan=idx.length+1;sr.appendChild(sc);body.appendChild(sr);
    rows.forEach(function(r){row(r[0],r[1],r[2])});
  });
  if(!any&&!diff){var er=document.createElement("tr");var ec=cell("td","المواصفات التفصيلية لهذي الفئات تتوفر عبر واتساب.","no");ec.colSpan=idx.length+1;er.appendChild(ec);body.appendChild(er)}
  if(!any&&diff){var er2=document.createElement("tr");var ec2=cell("td","ما فيه فروقات بين الفئات المختارة في المواصفات المدخلة.","no");ec2.colSpan=idx.length+1;er2.appendChild(ec2);body.appendChild(er2)}
  tb.style.setProperty("--n",idx.length);
  tb.appendChild(body);
  var tf=document.createElement("tfoot"),fr=document.createElement("tr");fr.appendChild(cell("td",""));
  idx.forEach(function(i){var c=cars[i],td=document.createElement("td"),a=document.createElement("a");a.className="btn";a.target="_blank";a.rel="noopener";a.textContent=c.status==="sold"?"اسأل عن مشابهة":"اطلب هذي الفئة";a.href=c.status==="sold"?wa("السلام عليكم، أبغى سيارة مشابهة لـ "+c.b+" "+c.n+" من "+SHOP):wa(msgFor(c,"بالدفع كاش"));td.appendChild(a);fr.appendChild(td)});
  tf.appendChild(fr);tb.appendChild(tf);
  wrap.appendChild(tb);
}
function drawPick(){
  var p=$("cmpPick");p.innerHTML="";
  cmpFam.forEach(function(i){var c=cars[i],b=document.createElement("button");b.type="button";b.className="chip";b.textContent=c.n;b.setAttribute("aria-pressed",cmpSel.indexOf(i)>-1?"true":"false");
    b.addEventListener("click",function(){var k=cmpSel.indexOf(i);if(k>-1){if(cmpSel.length>2)cmpSel.splice(k,1)}else{if(cmpSel.length>=4)cmpSel.shift();cmpSel.push(i)}cmpSel.sort(function(a,b){return a-b});drawPick();drawCmp()});p.appendChild(b)});
}
function openCmp(c){
  cmpFam=famOf(c);if(cmpFam.length<2)return;
  var ci=cars.indexOf(c);cmpSel=cmpFam.slice(0,4);
  if(cmpSel.indexOf(ci)<0&&ci>-1){cmpSel[cmpSel.length-1]=ci;cmpSel.sort(function(a,b){return a-b})}
  $("cmpT").textContent="مقارنة فئات "+c.b+" "+modelOf(c);$("cmpPick").hidden=false;$("cmp2").hidden=true;$("cmpHint").textContent="اختر الفئات اللي تبي تقارنها (من 2 إلى 4).";
  $("cmpDiff").checked=hasDiff(cmpSel);
  drawPick();drawCmp();
  var d=$("cmp");if($("dlg").open)$("dlg").close();
  if(d.showModal)d.showModal();else d.setAttribute("open","");
}
function openCmp2(c){
  var A=$("cmpA"),B=$("cmpB"),ci=cars.indexOf(c);A.innerHTML=B.innerHTML="";
  cars.forEach(function(x,i){if(x.status==="hidden")return;[A,B].forEach(function(S){var o=document.createElement("option");o.value=i;o.textContent=x.b+" "+x.n+" "+x.y;S.appendChild(o)})});
  A.value=ci;var other=-1;cars.forEach(function(x,i){if(other<0&&i!==ci&&x.status!=="hidden"&&x.status!=="sold"&&x.b===c.b&&x.n!==c.n)other=i});
  if(other<0)cars.forEach(function(x,i){if(other<0&&i!==ci&&x.status!=="hidden"&&x.status!=="sold")other=i});
  B.value=other;
  function go(){var a=+A.value,b=+B.value;if(a===b){var j=-1;cars.forEach(function(x,i){if(j<0&&i!==a&&x.status!=="hidden")j=i});b=j;B.value=b}cmpSel=[a,b];drawCmp()}
  A.onchange=go;B.onchange=go;
  $("cmpT").textContent="مقارنة بين سيارتين";$("cmpHint").textContent="اختر أي سيارتين من القائمتين تحت.";$("cmpPick").hidden=true;$("cmp2").hidden=false;$("cmpDiff").checked=false;{var ca=cars[+A.value],cb=cars[+B.value];$("cmpDiff").checked=!!(ca&&cb&&ca.b===cb.b&&modelOf(ca)===modelOf(cb)&&hasDiff([+A.value,+B.value]))}
  go();
  var d=$("cmp");if($("dlg").open)$("dlg").close();
  if(d.showModal)d.showModal();else d.setAttribute("open","");
}
